@namespace sv_a13d4295f1f54e31be517604b504b99f.Components.Pages.Settings
@using sv_a13d4295f1f54e31be517604b504b99f.Services

<div class="profile-section">
    <h2>Profile Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading profile...</p>
    }
    else
    {
        <div class="avatar-area">
            <div class="avatar-preview">
                @if (!string.IsNullOrEmpty(_avatarUrl))
                {
                    <img src="@_avatarUrl" alt="Avatar" />
                }
                else
                {
                    <div class="avatar-placeholder">👤</div>
                }
            </div>
            <div class="avatar-url">
                <label>Avatar URL</label>
                <input type="url" @bind="_avatarUrl" @bind:event="oninput" placeholder="https://example.com/avatar.png" />
            </div>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="_displayName" @bind:event="oninput" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="_email" @bind:event="oninput" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="_bio" @bind:event="oninput" rows="4"></textarea>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn-secondary" @onclick="Discard" disabled="@_saving">
                Discard Changes
            </button>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="toast @(_isError ? "toast-error" : "toast-success")">@_message</div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    private UserProfile? _savedProfile;
    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private bool _isError;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        _loading = true;
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(profile);
            _savedProfile = profile;
            _message = "Profile saved successfully!";
            _isError = false;
        }
        catch (Exception ex)
        {
            _message = $"Failed to save: {ex.Message}";
            _isError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private void Discard()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        _message = null;
    }
}

