toolArgs.file_text:
.notifications-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

.toggle-group {
    margin-bottom: 1.5rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1rem;
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    flex-shrink: 0;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-switch .slider {
    position: absolute;
    cursor: pointer;
    top: 0; left: 0; right: 0; bottom: 0;
    background: #ccc;
    border-radius: 24px;
    transition: 0.3s;
}

.toggle-switch .slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background: white;
    border-radius: 50%;
    transition: 0.3s;
}

.toggle-switch input:checked + .slider {
    background: #1976d2;
}

.toggle-switch input:checked + .slider::before {
    transform: translateX(20px);
}

.toggle-label {
    font-size: 0.95rem;
    color: #333;
}

.channels-section {
    margin-bottom: 1.5rem;
}

.channels-section h3 {
    font-size: 1rem;
    margin-bottom: 0.75rem;
    color: #555;
}

.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0.6rem;
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.channel-item:hover {
    background: #f5f5f5;
}

.button-group {
    margin-top: 1.5rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    background: #1976d2;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.toast-success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast-error {
    background: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

.loading {
    color: #888;
    font-style: italic;
}

