@@ -1,0 +1,230 @@
+@namespace sv_a13d4295f1f54e31be517604b504b99f.Components.Pages.Settings
+@using sv_a13d4295f1f54e31be517604b504b99f.Services
+
+<div class="security-section">
+    <h2>Security Settings</h2>
+
+    @if (_loading)
+    {
+        <p class="loading">Loading security settings...</p>
+    }
+    else
+    {
+        <!-- Change Password Panel -->
+        <div class="panel">
+            <div class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
+                <span>🔑 Change Password</span>
+                <span class="expand-icon">@(_passwordExpanded ? "▼" : "▶")</span>
+            </div>
+            @if (_passwordExpanded)
+            {
+                <div class="panel-body">
+                    <div class="form-group">
+                        <label>Current Password</label>
+                        <input type="password" @bind="_currentPassword" />
+                    </div>
+                    <div class="form-group">
+                        <label>New Password</label>
+                        <input type="password" @bind="_newPassword" />
+                    </div>
+                    <div class="form-group">
+                        <label>Confirm New Password</label>
+                        <input type="password" @bind="_confirmPassword" />
+                    </div>
+                    @if (!string.IsNullOrEmpty(_passwordError))
+                    {
+                        <div class="error-text">@_passwordError</div>
+                    }
+                    <button class="btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
+                        @(_changingPassword ? "Updating..." : "Update Password")
+                    </button>
+                    @if (!string.IsNullOrEmpty(_passwordSuccess))
+                    {
+                        <div class="success-text">@_passwordSuccess</div>
+                    }
+                </div>
+            }
+        </div>
+
+        <!-- Two-Factor Authentication -->
+        <div class="twofa-section">
+            <div class="twofa-row">
+                <div class="twofa-info">
+                    <h3>Two-Factor Authentication</h3>
+                    <span class="status-badge @(_twoFactorEnabled ? "status-enabled" : "status-disabled")">
+                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
+                    </span>
+                </div>
+                <label class="toggle-switch">
+                    <input type="checkbox" @bind="_twoFactorEnabled" />
+                    <span class="slider"></span>
+                </label>
+            </div>
+            @if (_lastPasswordChange.HasValue)
+            {
+                <p class="last-change">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
+            }
+        </div>
+
+        <!-- Active Sessions -->
+        <div class="sessions-section">
+            <h3>Active Sessions</h3>
+            @if (_sessions.Count == 0)
+            {
+                <p class="no-sessions">No active sessions found.</p>
+            }
+            else
+            {
+                <table class="sessions-table">
+                    <thead>
+                        <tr>
+                            <th>Device</th>
+                            <th>Location</th>
+                            <th>Last Active</th>
+                            <th></th>
+                        </tr>
+                    </thead>
+                    <tbody>
+                        @foreach (var session in _sessions)
+                        {
+                            <tr>
+                                <td>@session.Device</td>
+                                <td>@session.Location</td>
+                                <td>@session.LastActive.ToString("g")</td>
+                                <td>
+                                    @if (session != _sessions.FirstOrDefault())
+                                    {
+                                        <button class="btn-danger-sm" @onclick="() => ConfirmRevoke(session)">
+                                            Revoke
+                                        </button>
+                                    }
+                                    else
+                                    {
+                                        <span class="current-badge">Current</span>
+                                    }
+                                </td>
+                            </tr>
+                        }
+                    </tbody>
+                </table>
+            }
+        </div>
+
+        <!-- Revoke Confirmation Dialog -->
+        @if (_sessionToRevoke is not null)
+        {
+            <div class="dialog-overlay" @onclick="CancelRevoke">
+                <div class="dialog" @onclick:stopPropagation="true">
+                    <h4>Revoke Session</h4>
+                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
+                    <div class="dialog-buttons">
+                        <button class="btn-danger" @onclick="RevokeSessionAsync" disabled="@_revoking">
+                            @(_revoking ? "Revoking..." : "Yes, Revoke")
+                        </button>
+                        <button class="btn-secondary" @onclick="CancelRevoke" disabled="@_revoking">Cancel</button>
+                    </div>
+                </div>
+            </div>
+        }
+    }
+</div>
+
+@code {
+    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;
+
+    private bool _loading = true;
+    private bool _twoFactorEnabled;
+    private DateTime? _lastPasswordChange;
+    private List<ActiveSession> _sessions = new();
+
+    // Password change
+    private bool _passwordExpanded;
+    private string _currentPassword = "";
+    private string _newPassword = "";
+    private string _confirmPassword = "";
+    private string? _passwordError;
+    private string? _passwordSuccess;
+    private bool _changingPassword;
+
+    // Session revocation
+    private ActiveSession? _sessionToRevoke;
+    private bool _revoking;
+
+    protected override async Task OnInitializedAsync()
+    {
+        _loading = true;
+        var settings = await SettingsService.GetSecuritySettingsAsync();
+        _twoFactorEnabled = settings.TwoFactorEnabled;
+        _lastPasswordChange = settings.LastPasswordChange;
+        _sessions = settings.Sessions;
+        _loading = false;
+    }
+
+    private async Task ChangePasswordAsync()
+    {
+        _passwordError = null;
+        _passwordSuccess = null;
+
+        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
+        {
+            _passwordError = "All password fields are required.";
+            return;
+        }
+
+        if (_newPassword != _confirmPassword)
+        {
+            _passwordError = "New password and confirmation do not match.";
+            return;
+        }
+
+        _changingPassword = true;
+        try
+        {
+            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
+            _passwordSuccess = "Password updated successfully!";
+            _currentPassword = "";
+            _newPassword = "";
+            _confirmPassword = "";
+        }
+        catch (Exception ex)
+        {
+            _passwordError = ex.Message;
+        }
+        finally
+        {
+            _changingPassword = false;
+        }
+    }
+
+    private void ConfirmRevoke(ActiveSession session)
+    {
+        _sessionToRevoke = session;
+    }
+
+    private void CancelRevoke()
+    {
+        _sessionToRevoke = null;
+    }
+
+    private async Task RevokeSessionAsync()
+    {
+        if (_sessionToRevoke is null) return;
+
+        _revoking = true;
+        try
+        {
+            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
+            _sessions.Remove(_sessionToRevoke);
+            _sessionToRevoke = null;
+        }
+        catch
+        {
+            // Could show error, keeping simple
+        }
+        finally
+        {
+            _revoking = false;
+        }
+    }
+}
