toolArgs.file_text:
.security-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

.panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    cursor: pointer;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 0.8rem;
    color: #888;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    color: #555;
    font-size: 0.9rem;
}

.form-group input {
    width: 100%;
    max-width: 350px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.error-text {
    color: #c62828;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

.success-text {
    color: #2e7d32;
    font-size: 0.85rem;
    margin-top: 0.75rem;
}

.twofa-section {
    margin-bottom: 1.5rem;
    padding: 1rem;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
}

.twofa-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.twofa-info {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.twofa-info h3 {
    margin: 0;
    font-size: 1rem;
}

.status-badge {
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
}

.status-enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-disabled {
    background: #fff3e0;
    color: #e65100;
}

.last-change {
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #888;
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    flex-shrink: 0;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-switch .slider {
    position: absolute;
    cursor: pointer;
    top: 0; left: 0; right: 0; bottom: 0;
    background: #ccc;
    border-radius: 24px;
    transition: 0.3s;
}

.toggle-switch .slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background: white;
    border-radius: 50%;
    transition: 0.3s;
}

.toggle-switch input:checked + .slider {
    background: #1976d2;
}

.toggle-switch input:checked + .slider::before {
    transform: translateX(20px);
}

.sessions-section h3 {
    font-size: 1rem;
    margin-bottom: 0.75rem;
    color: #555;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #555;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    background: #1976d2;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-danger-sm {
    padding: 0.3rem 0.75rem;
    background: #e53935;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.8rem;
}

.btn-danger-sm:hover {
    background: #c62828;
}

.btn-danger {
    padding: 0.5rem 1.25rem;
    background: #e53935;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-danger:hover:not(:disabled) {
    background: #c62828;
}

.btn-danger:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-secondary {
    padding: 0.5rem 1.25rem;
    background: white;
    color: #555;
    border: 1px solid #ccc;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-secondary:hover:not(:disabled) {
    background: #f5f5f5;
}

.current-badge {
    font-size: 0.8rem;
    color: #1976d2;
    font-weight: 500;
}

.no-sessions {
    color: #888;
    font-style: italic;
}

/* Confirmation Dialog */
.dialog-overlay {
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: white;
    border-radius: 8px;
    padding: 1.5rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.dialog h4 {
    margin: 0 0 0.75rem 0;
    color: #333;
}

.dialog p {
    margin: 0 0 1.25rem 0;
    color: #555;
    font-size: 0.9rem;
    line-height: 1.4;
}

.dialog-buttons {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

.loading {
    color: #888;
    font-style: italic;
}

