@namespace sv_a13d4295f1f54e31be517604b504b99f.Components.Pages.Settings
@using sv_a13d4295f1f54e31be517604b504b99f.Services

<div class="appearance-section">
    <h2>Appearance Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="settings-grid">
            <!-- Theme Selector -->
            <div class="setting-group">
                <h3>Theme</h3>
                <div class="radio-group">
                    @foreach (var theme in _themes)
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="setting-group">
                <h3>Font Size</h3>
                <div class="radio-group">
                    @foreach (var size in _fontSizes)
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="setting-group">
                <h3>Language</h3>
                <select @bind="_language" class="language-select">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang.Key">@lang.Value</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="setting-group">
                <h3>Compact Mode</h3>
                <div class="toggle-item">
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_compactMode" />
                        <span class="slider"></span>
                    </label>
                    <span class="toggle-label">@(_compactMode ? "Enabled" : "Disabled")</span>
                </div>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="preview-area">
            <h3>Preview</h3>
            <div class="preview-box @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
                <div class="preview-card">
                    <span class="preview-card-title">Card Title</span>
                    <span class="preview-card-body">Card content appears here with your chosen styling.</span>
                </div>
            </div>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save")
            </button>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="toast @(_isError ? "toast-error" : "toast-success")">@_message</div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private bool _isError;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Español",
        ["fr"] = "Français",
        ["de"] = "Deutsch",
        ["ja"] = "日本語",
        ["zh"] = "中文"
    };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_fontSize.ToLowerInvariant()}");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _message = "Appearance settings saved!";
            _isError = false;
        }
        catch (Exception ex)
        {
            _message = $"Failed to save: {ex.Message}";
            _isError = true;
        }
        finally
        {
            _saving = false;
        }
    }
}

.appearance-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

.settings-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
}

.setting-group h3 {
    font-size: 0.95rem;
    margin: 0 0 0.75rem 0;
    color: #555;
}

.radio-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.language-select {
    width: 100%;
    max-width: 200px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.9rem;
    background: white;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    flex-shrink: 0;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-switch .slider {
    position: absolute;
    cursor: pointer;
    top: 0; left: 0; right: 0; bottom: 0;
    background: #ccc;
    border-radius: 24px;
    transition: 0.3s;
}

.toggle-switch .slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background: white;
    border-radius: 50%;
    transition: 0.3s;
}

.toggle-switch input:checked + .slider {
    background: #1976d2;
}

.toggle-switch input:checked + .slider::before {
    transform: translateX(20px);
}

.toggle-label {
    font-size: 0.9rem;
    color: #555;
}

/* Preview Area */
.preview-area {
    margin-bottom: 1.5rem;
}

.preview-area h3 {
    font-size: 0.95rem;
    margin: 0 0 0.75rem 0;
    color: #555;
}

.preview-box {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.25rem;
    transition: all 0.3s ease;
}

/* Theme previews */
.preview-theme-light {
    background: #ffffff;
    color: #333;
}

.preview-theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-theme-system {
    background: #f8f9fa;
    color: #333;
}

/* Font size previews */
.preview-font-small .preview-text {
    font-size: 0.8rem;
}

.preview-font-medium .preview-text {
    font-size: 0.95rem;
}

.preview-font-large .preview-text {
    font-size: 1.1rem;
}

.preview-font-small .preview-header {
    font-size: 1rem;
}

.preview-font-medium .preview-header {
    font-size: 1.2rem;
}

.preview-font-large .preview-header {
    font-size: 1.4rem;
}

/* Compact mode preview */
.preview-compact {
    padding: 0.75rem;
}

.preview-compact .preview-text {
    margin: 0.25rem 0;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

.preview-header {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin: 0.5rem 0;
    line-height: 1.5;
}

.preview-card {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    padding: 0.75rem;
    border-radius: 4px;
    margin-top: 0.75rem;
    border: 1px solid currentColor;
    opacity: 0.7;
}

.preview-card-title {
    font-weight: 600;
    font-size: 0.9em;
}

.preview-card-body {
    font-size: 0.85em;
    opacity: 0.8;
}

.button-group {
    margin-top: 1.5rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    background: #1976d2;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.toast-success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast-error {
    background: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

.loading {
    color: #888;
    font-style: italic;
}

