.appearance-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

.settings-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
}

.setting-group h3 {
    font-size: 0.95rem;
    margin: 0 0 0.75rem 0;
    color: #555;
}

.radio-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.language-select {
    width: 100%;
    max-width: 200px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.9rem;
    background: white;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    flex-shrink: 0;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-switch .slider {
    position: absolute;
    cursor: pointer;
    top: 0; left: 0; right: 0; bottom: 0;
    background: #ccc;
    border-radius: 24px;
    transition: 0.3s;
}

.toggle-switch .slider::before {
    content: "";
    position: absolute;
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background: white;
    border-radius: 50%;
    transition: 0.3s;
}

.toggle-switch input:checked + .slider {
    background: #1976d2;
}

.toggle-switch input:checked + .slider::before {
    transform: translateX(20px);
}

.toggle-label {
    font-size: 0.9rem;
    color: #555;
}

/* Preview Area */
.preview-area {
    margin-bottom: 1.5rem;
}

.preview-area h3 {
    font-size: 0.95rem;
    margin: 0 0 0.75rem 0;
    color: #555;
}

.preview-box {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.25rem;
    transition: all 0.3s ease;
}

/* Theme previews */
.preview-theme-light {
    background: #ffffff;
    color: #333;
}

.preview-theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-theme-system {
    background: #f8f9fa;
    color: #333;
}

/* Font size previews */
.preview-font-small .preview-text {
    font-size: 0.8rem;
}

.preview-font-medium .preview-text {
    font-size: 0.95rem;
}

.preview-font-large .preview-text {
    font-size: 1.1rem;
}

.preview-font-small .preview-header {
    font-size: 1rem;
}

.preview-font-medium .preview-header {
    font-size: 1.2rem;
}

.preview-font-large .preview-header {
    font-size: 1.4rem;
}

/* Compact mode preview */
.preview-compact {
    padding: 0.75rem;
}

.preview-compact .preview-text {
    margin: 0.25rem 0;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

.preview-header {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin: 0.5rem 0;
    line-height: 1.5;
}

.preview-card {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    padding: 0.75rem;
    border-radius: 4px;
    margin-top: 0.75rem;
    border: 1px solid currentColor;
    opacity: 0.7;
}

.preview-card-title {
    font-weight: 600;
    font-size: 0.9em;
}

.preview-card-body {
    font-size: 0.85em;
    opacity: 0.8;
}

.button-group {
    margin-top: 1.5rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    background: #1976d2;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.toast-success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast-error {
    background: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

.loading {
    color: #888;
    font-style: italic;
}

